import json
from typing import Literal, Optional

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class BotsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.bots.api_bot")
    def api_bot(
        self,
        permissions: Optional[list[Literal["can_create_chats", "can_write_first"]]],
        sort: str = "name.asc",
        offset: int = 0,
        limit: int = 0,
    ):
        """
        Получение списка ботов с возможностью сортировки,
        фильтрации и страничной навигации
        """
        return self.get(
            path="api/bot",
            permissions=json.dumps(permissions),
            sort=sort,
            offset=offset,
            limit=limit,
        )

    @tracer.start_as_current_span("admin.bots.api_bot_id")
    def api_bot_id(self, bot_id):
        """
        Получение данных бота
        """
        return self.get(path=f"api/bot/{bot_id}")

    @tracer.start_as_current_span("admin.bots.patch_api_bot_id")
    def patch_api_bot_id(
        self,
        bot_id,
        permissions: list[Literal["can_create_chats", "can_write_first"]],
    ):
        """
        Обновление полномочий бота
        """
        return self.patch(path=f"api/bot/{bot_id}", json={"permissions": permissions})
